insert into document_template_sections (document_template_id, code, title, sort_order, content_type, html_template, source_content_block_type, content_block_scope) values
('organigramme_fiches_poste', 'organigramme_table', 'Organigramme fonctionnel', 1, 'rich_text', '<table><thead><tr><th>Fonction</th><th>Responsable</th><th>Missions principales</th></tr></thead><tbody>
