<tr><td>Pédagogique</td><td>{{pedagogical_referent_name}}</td><td>Conception et animation des formations, suivi pédagogique des stagiaires</td></tr>
<tr><td>Administratif</td><td>{{administrative_referent_name}}</td><td>Gestion des dossiers, convocations, conventions, suivi des financements</td></tr>
<tr><td>Référent Handicap</td><td>{{disability_referent_name}}</td><td>Accueil et accompagnement des PSH, adaptation des parcours</td></tr>
<tr><td>Commercial / Communication</td><td>{{director_name}}</td><td>Promotion des formations, prospection, suivi des clients</td></tr>
<tr><td>Technique / Digital</td><td>{{technical_provider_name}}</td><td>Outils numériques, plateformes e-learning, assistance technique</td></tr>
</tbody></table>
<p>{{sole_practitioner_note}}</p>', null, 'global'),
('organigramme_fiches_poste', 'referents_contacts', 'Référents et intervenants', 2, 'rich_text', '<p><strong>Référents internes :</strong></p>
<ul>
